#include <bits/stdc++.h>
using namespace std;

#define ITER(i, s, e) for(int i=s; i<=e; ++i)
#define REVERSE_ITER(i, s, e) for(int i=s; i>=e; --i)

typedef long long ll;

inline int input() {
    int x=0, sign=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { sign=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*sign;
}

inline ll inputLong() {
    ll x=0; int s=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { s=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*s;
}

const int MAXN=32, MOD=1000000007;

void add_mod(int &x, int y) {
    x+=y; if(x>=MOD) x-=MOD;
}

struct Matrix {
    int mat[MAXN][MAXN];
    void init() { memset(mat,0,sizeof(mat)); }
    void print() {
        ITER(i,1,n+1) {
            ITER(j,1,n+1) printf("%d%c", mat[i][j], j==n?'\n':' ');
        }
        putchar('\n');
    }
    Matrix operator*(const Matrix &rhs) const {
        Matrix res; res.init();
        ITER(i,1,n+1) ITER(j,1,n+1) ITER(k,1,n+1)
            add_mod(res.mat[i][j], (ll)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
Matrix E, A[MAXN], pre[MAXN], suf[MAXN], answer;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m= inputLong(); n= input();
    memset(&E,0,sizeof(E));
    ITER(i,1,n) E.mat[i][i]=1;
    answer=E;
    ITER(i,1,n) {
        A[i]=E;
        A[i].mat[i][i]=1;
    }
    pre[0]=E; suf[n+1]=E;

    for(;m; m/=n) {
        ll u=m%n;
        if(u) {
            ll s=0, v=m/n;
            while(v) { s=(s+v%n)%n; v/=n; }
            u=(s+u-1)%n+1;
            for(; u!=s; --u) {
                if(u<=0) u+=n;
                answer=A[u]*answer;
            }
        }
        ITER(i,1,n) pre[i]=pre[i-1]*A[i];
        for(int i=n; i>=1; --i) suf[i]=A[i]*suf[i+1];
        ITER(i,1,n) A[i]=suf[i]*pre[i-1];
    }
    int res=1;
    ITER(i,1,n) add_mod(res, answer.mat[n+1][i]);
    printf("%d\n", res);
    return 0;
}
